import sys
import os
import json
import re
import collections
from decimal import Decimal


def format_date(val):
    if val is None or val == "":
        return None
    d = str(val).strip()
    m = re.match(r"^(\d{4})-(\d{1,2})-(\d{1,2})", d)
    if m:
        year, month, day = m.groups()
        return f"{int(year):04d}-{int(month):02d}-{int(day):02d}"
    return d


def parse_amount(val):
    if val is None or val == "":
        return None
    if isinstance(val, Decimal):
        return val
    try:
        return Decimal(str(val))
    except Exception:
        return None


def format_amount(d):
    return f"{d:f}"


def get_fact_value(awards, fact_name):
    doc_name = "usaspending_awards"

    if fact_name == "performance start":
        values = []
        for aw in awards:
            pop = aw.get("period_of_performance") or {}
            val = pop.get("start_date")
            val_clean = format_date(val)
            if val_clean is not None:
                values.append(val_clean)
        if not values:
            return "ABSENT"
        if len(set(values)) > 1:
            return "CONFLICT"
        return [values[0], doc_name]

    elif fact_name == "performance end":
        values = []
        for aw in awards:
            pop = aw.get("period_of_performance") or {}
            val = pop.get("end_date")
            val_clean = format_date(val)
            if val_clean is not None:
                values.append(val_clean)
        if not values:
            return "ABSENT"
        if len(set(values)) > 1:
            return "CONFLICT"
        return [values[0], doc_name]

    elif fact_name == "amount obligated":
        values = []
        for aw in awards:
            val = aw.get("total_obligation")
            val_parsed = parse_amount(val)
            if val_parsed is not None:
                values.append(val_parsed)
        if not values:
            return "ABSENT"
        if any(v != values[0] for v in values):
            return "CONFLICT"
        return [format_amount(values[0]), doc_name]

    elif fact_name == "potential value":
        values = []
        for aw in awards:
            val = aw.get("base_and_all_options")
            val_parsed = parse_amount(val)
            if val_parsed is not None:
                values.append(val_parsed)
        if not values:
            return "ABSENT"
        if any(v != values[0] for v in values):
            return "CONFLICT"
        return [format_amount(values[0]), doc_name]

    return "ABSENT"


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    awards_file = os.path.join(packet_dir, "usaspending_awards.json")
    if os.path.exists(awards_file):
        with open(awards_file, "r", encoding="utf-8") as f:
            awards_data = json.load(f, parse_float=Decimal, parse_int=Decimal)
    else:
        awards_data = []

    awards_by_id = collections.defaultdict(list)
    for award in awards_data:
        aid = award.get("generated_unique_award_id")
        if aid:
            awards_by_id[aid].append(award)

    output = {}
    pairs = manifest.get("pairs", [])
    facts_map = manifest.get("facts", {})

    for pair in pairs:
        if "::" in pair:
            rule_id, entity = pair.split("::", 1)
        else:
            rule_id, entity = pair, ""

        facts_for_rule = facts_map.get(rule_id, [])
        matching_awards = awards_by_id.get(entity, [])

        pair_result = {}
        for fact_name in facts_for_rule:
            pair_result[fact_name] = get_fact_value(matching_awards, fact_name)

        output[pair] = pair_result

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()

