import sys
import os
import json
import re
from decimal import Decimal
from collections import defaultdict


def parse_decimal(val):
    if val is None:
        return None
    if isinstance(val, str):
        val = val.strip()
        if not val:
            return None
        try:
            return Decimal(val)
        except Exception:
            return None
    if isinstance(val, (int, float, Decimal)):
        return val if isinstance(val, Decimal) else Decimal(str(val))
    return None


def parse_date(val):
    if val is None:
        return None
    val = str(val).strip()
    if not val:
        return None
    m = re.match(r"^(\d{4}-\d{2}-\d{2})", val)
    if m:
        return m.group(1)
    return None


def extract_perf_start(award):
    pop = award.get("period_of_performance") or {}
    return parse_date(pop.get("start_date"))


def extract_perf_end(award):
    pop = award.get("period_of_performance") or {}
    return parse_date(pop.get("end_date"))


def extract_amount_obligated(award):
    return parse_decimal(award.get("total_obligation"))


def extract_potential_value(award):
    return parse_decimal(award.get("base_and_all_options"))


FACT_CONFIG = {
    "performance start": (extract_perf_start, "usaspending_awards", "date"),
    "performance end": (extract_perf_end, "usaspending_awards", "date"),
    "amount obligated": (extract_amount_obligated, "usaspending_awards", "amount"),
    "potential value": (extract_potential_value, "usaspending_awards", "amount"),
}


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    # Load awards file
    awards_file = os.path.join(packet_dir, "usaspending_awards.json")
    if not os.path.exists(awards_file):
        for root, dirs, files in os.walk(packet_dir):
            if "usaspending_awards.json" in files:
                awards_file = os.path.join(root, "usaspending_awards.json")
                break

    records_by_entity = defaultdict(list)
    if os.path.exists(awards_file):
        try:
            with open(awards_file, "r", encoding="utf-8") as f:
                awards_data = json.load(f, parse_float=Decimal, parse_int=Decimal)
                if isinstance(awards_data, list):
                    for award in awards_data:
                        gen_id = award.get("generated_unique_award_id")
                        if gen_id:
                            records_by_entity[str(gen_id)].append(award)
                        num_id = award.get("id")
                        if num_id is not None:
                            records_by_entity[str(num_id)].append(award)
        except Exception:
            pass

    pairs = manifest.get("pairs", [])
    facts_map = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        if "::" in pair:
            rule_id, entity = pair.split("::", 1)
        else:
            rule_id, entity = pair, ""

        rule_facts = facts_map.get(rule_id, [])
        matching_records = records_by_entity.get(entity, [])

        pair_result = {}

        for fact_name in rule_facts:
            config = FACT_CONFIG.get(fact_name)
            if not config:
                pair_result[fact_name] = "ABSENT"
                continue

            extractor, doc_name, val_type = config
            raw_values = [extractor(r) for r in matching_records]
            valid_values = [v for v in raw_values if v is not None]

            if not valid_values:
                pair_result[fact_name] = "ABSENT"
            else:
                first = valid_values[0]
                if all(v == first for v in valid_values):
                    if val_type == "amount":
                        val_str = f"{first:f}"
                    else:
                        val_str = str(first)
                    pair_result[fact_name] = [val_str, doc_name]
                else:
                    pair_result[fact_name] = "CONFLICT"

        output[pair] = pair_result

    print(json.dumps(output, indent=1))


if __name__ == "__main__":
    main()

