import sys
import os
import json
from decimal import Decimal

RULES = {
    "usa.period_3y": {
        "performance start": ("usaspending_awards", ["period_of_performance", "start_date"], "date"),
        "performance end": ("usaspending_awards", ["period_of_performance", "end_date"], "date"),
    },
    "usa.obligated_95": {
        "amount obligated": ("usaspending_awards", ["total_obligation"], "amount"),
        "potential value": ("usaspending_awards", ["base_and_all_options"], "amount"),
    },
}

def get_nested(obj, path):
    curr = obj
    for p in path:
        if isinstance(curr, dict):
            curr = curr.get(p)
        else:
            return None
    return curr

def load_documents(packet_dir):
    docs = {}
    if not os.path.isdir(packet_dir):
        return docs
    for fname in os.listdir(packet_dir):
        if fname.endswith(".json"):
            doc_name = fname[:-5]
            fpath = os.path.join(packet_dir, fname)
            try:
                with open(fpath, "r", encoding="utf-8") as f:
                    docs[doc_name] = json.load(f, parse_float=Decimal, parse_int=Decimal)
            except Exception:
                pass
    return docs

def build_award_index(records):
    index = {}
    if not isinstance(records, list):
        return index
    for item in records:
        if not isinstance(item, dict):
            continue
        award_id = item.get("generated_unique_award_id")
        if award_id:
            index.setdefault(str(award_id), []).append(item)
    return index

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    docs = load_documents(packet_dir)

    doc_indexes = {}
    for doc_name, data in docs.items():
        doc_indexes[doc_name] = build_award_index(data)

    pairs = manifest.get("pairs", [])
    facts_spec = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        if "::" in pair:
            rule_id, entity = pair.split("::", 1)
        else:
            rule_id, entity = "", pair

        fact_names = facts_spec.get(rule_id, [])
        pair_result = {}

        for fact_name in fact_names:
            rule_def = RULES.get(rule_id, {}).get(fact_name)
            if not rule_def:
                for r_rules in RULES.values():
                    if fact_name in r_rules:
                        rule_def = r_rules[fact_name]
                        break

            if not rule_def:
                pair_result[fact_name] = "ABSENT"
                continue

            doc_name, path, val_type = rule_def
            index = doc_indexes.get(doc_name, {})
            records = index.get(entity, [])

            values = []
            for record in records:
                raw_val = get_nested(record, path)
                if raw_val is None or raw_val == "":
                    continue

                if val_type == "date":
                    val_str = str(raw_val).strip()
                    if len(val_str) >= 10:
                        val_str = val_str[:10]
                    values.append(val_str)
                elif val_type == "amount":
                    values.append(raw_val)
                else:
                    values.append(raw_val)

            if not values:
                pair_result[fact_name] = "ABSENT"
            else:
                first = values[0]
                if all(v == first for v in values):
                    pair_result[fact_name] = [str(first), doc_name]
                else:
                    pair_result[fact_name] = "CONFLICT"

        output[pair] = pair_result

    print(json.dumps(output, indent=1))

if __name__ == "__main__":
    main()

