import sys
import os
import json
from collections import defaultdict
from decimal import Decimal, InvalidOperation

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    # Load usaspending_awards.json
    awards_path = os.path.join(packet_dir, "usaspending_awards.json")
    awards = []
    if os.path.exists(awards_path):
        with open(awards_path, "r", encoding="utf-8") as f:
            try:
                awards = json.load(f, parse_float=Decimal, parse_int=Decimal)
            except Exception:
                awards = []

    # Index awards by generated_unique_award_id and id
    records_by_entity = defaultdict(list)
    for award in awards:
        if not isinstance(award, dict):
            continue
        seen_keys = set()
        gid = award.get("generated_unique_award_id")
        if gid:
            seen_keys.add(str(gid))
        aid = award.get("id")
        if aid is not None:
            seen_keys.add(str(aid))
        for k in seen_keys:
            records_by_entity[k].append(award)

    # Fact definitions
    FACT_SPECS = {
        "performance start": {
            "doc": "usaspending_awards",
            "type": "date",
            "getter": lambda a: a.get("period_of_performance", {}).get("start_date") if isinstance(a.get("period_of_performance"), dict) else None,
        },
        "performance end": {
            "doc": "usaspending_awards",
            "type": "date",
            "getter": lambda a: a.get("period_of_performance", {}).get("end_date") if isinstance(a.get("period_of_performance"), dict) else None,
        },
        "amount obligated": {
            "doc": "usaspending_awards",
            "type": "amount",
            "getter": lambda a: a.get("total_obligation"),
        },
        "potential value": {
            "doc": "usaspending_awards",
            "type": "amount",
            "getter": lambda a: a.get("base_and_all_options"),
        },
    }

    pairs = manifest.get("pairs", [])
    facts_by_rule = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        if "::" in pair:
            rule_id, entity = pair.split("::", 1)
        else:
            rule_id, entity = pair, ""

        rule_facts = facts_by_rule.get(rule_id, [])
        matching_awards = records_by_entity.get(entity, [])

        pair_result = {}

        for fact_name in rule_facts:
            spec = FACT_SPECS.get(fact_name)
            if not spec:
                pair_result[fact_name] = "ABSENT"
                continue

            doc_name = spec["doc"]
            val_type = spec["type"]
            getter = spec["getter"]

            extracted_vals = []
            for award in matching_awards:
                try:
                    val = getter(award)
                except Exception:
                    val = None

                if val is not None and val != "":
                    if val_type == "date":
                        norm_str = str(val).strip()[:10]
                        extracted_vals.append((norm_str, norm_str))
                    elif val_type == "amount":
                        raw_str = str(val).replace("$", "").replace(",", "").strip()
                        try:
                            dec_val = Decimal(raw_str)
                            extracted_vals.append((dec_val, str(val).strip()))
                        except InvalidOperation:
                            extracted_vals.append((raw_str, raw_str))
                    else:
                        extracted_vals.append((str(val), str(val)))

            if not extracted_vals:
                pair_result[fact_name] = "ABSENT"
            else:
                first_norm, first_display = extracted_vals[0]
                has_conflict = False
                for norm_val, _ in extracted_vals[1:]:
                    if norm_val != first_norm:
                        has_conflict = True
                        break

                if has_conflict:
                    pair_result[fact_name] = "CONFLICT"
                else:
                    pair_result[fact_name] = [first_display, doc_name]

        output[pair] = pair_result

    print(json.dumps(output, indent=1))

if __name__ == "__main__":
    main()

