import json
import os
import sys
from decimal import Decimal


FACT_FIELD_MAP = {
    "performance start": ("period_of_performance.start_date", "date"),
    "performance end": ("period_of_performance.end_date", "date"),
    "amount obligated": ("total_obligation", "amount"),
    "potential value": ("base_and_all_options", "amount"),
}


def get_nested(record, path):
    curr = record
    for part in path.split("."):
        if isinstance(curr, dict):
            curr = curr.get(part)
        else:
            return None
    return curr


def format_value(raw_val, val_type):
    if raw_val is None:
        return None
    if val_type == "date":
        s = str(raw_val).strip()
        if not s:
            return None
        return s[:10]
    elif val_type == "amount":
        if isinstance(raw_val, str) and not raw_val.strip():
            return None
        try:
            d = Decimal(str(raw_val))
            return str(d)
        except Exception:
            return str(raw_val)
    return str(raw_val)


def values_agree(v1, v2, val_type):
    if val_type == "amount":
        try:
            return Decimal(v1) == Decimal(v2)
        except Exception:
            return v1 == v2
    return v1 == v2


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    # Locate usaspending_awards.json
    doc_name = "usaspending_awards"
    awards_file = os.path.join(packet_dir, f"{doc_name}.json")
    if not os.path.isfile(awards_file):
        for fname in os.listdir(packet_dir):
            if fname.lower() == f"{doc_name}.json".lower():
                awards_file = os.path.join(packet_dir, fname)
                break

    awards_by_id = {}
    if os.path.isfile(awards_file):
        with open(awards_file, "r", encoding="utf-8") as f:
            data = json.load(f, parse_float=Decimal, parse_int=Decimal)
            if isinstance(data, list):
                for item in data:
                    award_id = item.get("generated_unique_award_id")
                    if award_id:
                        awards_by_id.setdefault(award_id, []).append(item)

    pairs = manifest.get("pairs", [])
    facts_by_rule = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        rule_id, entity_id = pair.split("::", 1)
        rule_facts = facts_by_rule.get(rule_id, [])
        pair_result = {}

        records = awards_by_id.get(entity_id, [])

        for fact_name in rule_facts:
            mapping = FACT_FIELD_MAP.get(fact_name)
            if not mapping:
                pair_result[fact_name] = "ABSENT"
                continue

            field_path, val_type = mapping

            if not records:
                pair_result[fact_name] = "ABSENT"
                continue

            extracted_values = []
            for record in records:
                raw_val = get_nested(record, field_path)
                formatted = format_value(raw_val, val_type)
                if formatted is not None:
                    extracted_values.append(formatted)

            if not extracted_values:
                pair_result[fact_name] = "ABSENT"
            else:
                first_val = extracted_values[0]
                has_conflict = False
                for other_val in extracted_values[1:]:
                    if not values_agree(first_val, other_val, val_type):
                        has_conflict = True
                        break

                if has_conflict:
                    pair_result[fact_name] = "CONFLICT"
                else:
                    pair_result[fact_name] = [first_val, doc_name]

        output[pair] = pair_result

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()

